/**
 * Статический импорт PNG.
 *
 * Expo объявляет типы для `*.jpg` (см. `packages/api/src/assets.d.ts` — там
 * тот же приём ради `tsc` вне приложения), а для `*.png` в этом проекте
 * объявления не было: до сих пор PNG подключались только через `require`,
 * которому типы не нужны. Фирменной странице Ocean Basket нужен именно
 * импорт — модуль с её ассетами читает и тестовый прогон, а `require(".png")`
 * Node на этапе выполнения разобрать не может.
 *
 * Metro и так резолвит картинку на этапе сборки; это объявление нужно только
 * `tsc --noEmit`.
 */
declare module "*.png" {
  const value: number;
  export default value;
}
